 function openRules(){const modal=$('modal');modal.innerHTML=`<div class="big-emoji">📖</div><h2>كيف تلعب؟</h2><p>في كل دور تحصل على نقطة أكشن إضافية (حتى 7)، وتسحب بطاقة. انقر بطاقة من يدك ثم اختر ممرّك؛ أو اسحبها إليه مباشرة.<br><br><b>المخلوقات</b> تستدعى إلى ممرّ خالٍ وتهاجم خصمها المقابل. إن كان الممر فارغاً، تضرب صحة الخصم مباشرة.<br><b>التعويذات</b> تؤثر على الممر المختار. استخدم زر «فْلوب» لتفعيل قدرة مخلوقك مقابل نقطة أكشن. كل مخلوق يهاجم مرة واحدة في الدور.<br><br>اخفض صحة حارس القمر إلى الصفر لتفوز!<br><small>هذه لعبة خيالية أصلية، ببطاقات وشخصيات مرسومة بالإيموجي.</small></p><button class="action-btn secondary" id="closeRules">فهمت!</button>`;$('modalBackdrop').classList.add('open');$('closeRules').onclick=()=>$('modalBackdrop').classList.remove('open')}
 function reset(){state=freshState();state.handSelected=null;draw(state.player,5);draw(state.enemy,5);$('modalBackdrop').classList.remove('open');$('battleLog').innerHTML='';state.log=[];log('بدأت مغامرة جديدة!');render();notify('🍓 حظاً موفقاً يا مستكشف السُحب!')}
 // Board interaction, click-to-play and click-to-attack.
 playerLanes.addEventListener('click',e=>{const lane=e.target.closest('.lane');if(!lane)return;const i=Number(lane.dataset.lane);if(state.floopTarget){state.floopTarget=false;floopUnit(i);return}if(state.handSelected!==null){playFromHand(state.handSelected,i);return}const unit=state.player.board[i];if(unit&&!unit.building){if(!unit.attacked){attackLane(i);playSound(360)}else notify('هذا المخلوق هاجم بالفعل في هذا الدور')}else hint('اختر بطاقة من يدك أولاً')});
-enemyLanes.addEventListener('click',e=>{const lane=e.target.closest('.lane');if(!lane)return;if(state.handSelected!==null){const c=catalog[state.player.hand[state.handSelected]];if(c.type==='spell'&&c.id==='zap')playFromHand(state.handSelected,Number(lane.dataset.lane));else notify('اختر ممرّاً من مملكتك لوضع هذه البطاقة');return}hint('مخلوقاتك تهاجم خصمها عند الضغط على ممرّك')});
+enemyLanes.addEventListener('click',e=>{const lane=e.target.closest('.lane');if(!lane)return;if(state.handSelected!==null){const c=catalog[state.player.hand[state.handSelected]];if(state.player.hand[state.handSelected]==='zap')playFromHand(state.handSelected,Number(lane.dataset.lane));else notify('اختر ممرّاً من مملكتك لوضع هذه البطاقة');return}hint('مخلوقاتك تهاجم خصمها عند الضغط على ممرّك')});
 $('hand').addEventListener('click',e=>{const card=e.target.closest('.hand-card');if(card)selectCard(Number(card.dataset.index))});
 $('hand').addEventListener('dragstart',e=>{const card=e.target.closest('.hand-card');if(!card)return;state.handSelected=Number(card.dataset.index);e.dataTransfer.setData('text/plain',card.dataset.index);e.dataTransfer.effectAllowed='move';setTimeout(renderHand,0)});
 [playerLanes,enemyLanes].forEach(root=>{root.addEventListener('dragover',e=>{if(e.target.closest('.lane')){e.preventDefault();e.dataTransfer.dropEffect='move'}});root.addEventListener('drop',e=>{const lane=e.target.closest('.lane');if(!lane)return;e.preventDefault();const index=Number(e.dataTransfer.getData('text/plain'));if(root===playerLanes)playFromHand(index,Number(lane.dataset.lane));else{const c=catalog[state.player.hand[index]];if(c?.id==='zap')playFromHand(index,Number(lane.dataset.lane));else notify('اسحب البطاقة إلى أحد ممرّاتك')}})});
 $('floopBtn').addEventListener('click',()=>{if(state.turn!=='player')return;const candidates=state.player.board.filter(u=>u&&catalog[u.id].type==='creature'&&!u.flooped);if(!candidates.length){notify('لا يوجد مخلوق جاهز للفْلوب');return}if(state.player.ap<1){notify('تحتاج نقطة أكشن واحدة للفْلوب');return}state.floopTarget=!state.floopTarget;state.handSelected=null;render();hint(state.floopTarget?'اختر مخلوقاً في ممرّك لتفعيل الفْلوب':'تم إلغاء اختيار الفْلوب')});

